import 'package:flutter/material.dart'; import '../../../core/conversation_entry.dart';
class ConversationTimeline extends StatelessWidget {
 const ConversationTimeline({super.key,required this.entries,this.height=135,this.compact=false});
 final List<ConversationEntry> entries; final double height; final bool compact;
 String _time(DateTime t)=>'${t.hour.toString().padLeft(2,'0')}:${t.minute.toString().padLeft(2,'0')}';
 @override Widget build(BuildContext context)=>Container(height:height,padding:EdgeInsets.all(compact?10:12),decoration:BoxDecoration(color:Colors.black.withValues(alpha:.38),borderRadius:BorderRadius.circular(14),border:Border.all(color:Colors.cyanAccent.withValues(alpha:.35))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Text('CONVERSATION LOG',style:TextStyle(color:Colors.cyanAccent,fontSize:compact?10:12,fontWeight:FontWeight.bold,letterSpacing:1.2)),const SizedBox(width:8),const Expanded(child:Divider(color:Colors.cyanAccent,thickness:.4))]),const SizedBox(height:6),if(entries.isEmpty) Expanded(child:Center(child:Text('NO ACTIVE CONVERSATION',style:TextStyle(color:Colors.white38,fontSize:compact?9:11,letterSpacing:1.2)))) else Expanded(child:ListView.builder(padding:EdgeInsets.zero,itemCount:entries.length,itemBuilder:(context,index){final e=entries[index];return Row(crossAxisAlignment:CrossAxisAlignment.start,children:[SizedBox(width:compact?34:38,child:Text(_time(e.timestamp),style:TextStyle(color:Colors.white38,fontSize:compact?9:10))),SizedBox(width:compact?44:48,child:Text(e.isUser?'USER':'JARVIS',style:TextStyle(color:e.isUser?Colors.blueAccent:Colors.greenAccent,fontSize:compact?9:10,fontWeight:FontWeight.bold))),Expanded(child:Text(e.text,maxLines:2,overflow:TextOverflow.ellipsis,style:TextStyle(color:e.isUser?Colors.white70:Colors.greenAccent,fontSize:compact?10:11)))]);} ))]));
}
